"# Check recent conversations and background processes
$brainPath = "C:\Users\Admin\.gemini\antigravity-ide\brain"
Write-Host "=== CONVERSATION FOLDERS MODIFIED IN LAST 24 HOURS ==="
if (Test-Path $brainPath) {
    Get-ChildItem -Path $brainPath -Directory | Where-Object { $_.LastWriteTime -gt (Get-Date).AddDays(-1) } | Select-Object Name, LastWriteTime, CreationTime | Format-Table -AutoSize
} else {
    Write-Host "Brain path not found."
}

Write-Host "=== CHECKING RECENT TRANSCRIPT LOGS ==="
$recentLogs = Get-ChildItem -Path "$brainPath\*\.system_generated\logs\*.jsonl" -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -gt (Get-Date).AddDays(-1) }
if ($recentLogs) {
    $recentLogs | Select-Object FullName, LastWriteTime, Length | Format-Table -AutoSize
} else {
    Write-Host "No recent transcript log files modified in the last 24 hours."
}

Write-Host "=== RUNNING PROCESSES (NODE / ELECTRON / GEMINI / AGY) ==="
Get-Process | Where-Object { $_.Name -match 'antigravity|gemini|agy|electron|node' } | Select-Object Id, ProcessName, StartTime, CPU, WorkingSet64 | Format-Table -AutoSize
"

"# Inspect last conversation transcript to see what happened yesterday
$lastConv = "C:\Users\Admin\.gemini\antigravity-ide\brain\e1528e1e-9b55-4671-a54e-f14684a0bbeb\.system_generated\logs\transcript.jsonl"
if (Test-Path $lastConv) {
    Get-Content $lastConv -Tail 20
} else {
    Write-Host "Transcript not found."
}
"
